 "content": "def transform(grid):
    """Encode counts of horizontal runs of colors 3 and 2 in a 2x3 grid."""
    counts = {3: 0, 2: 0}
    for row in grid:
        previous = None
        for value in row:
            if value in counts and value != previous:
                counts[value] += 1
            previous = value
    values = [3] * counts[3] + [2] * counts[2]
    values = (values + [0] * 6)[:6]
    return [values[:3], values[3:]]
